/**
 * Generates packages/studio/src/font-metrics.data.ts from real font files.
 *
 *   tsx scripts/generate-font-metrics.ts <out.ts> <faceKey=path> [<faceKey=path> ...]
 *
 * faceKey is "<fontId>:<REGULAR|BOLD>" (see packages/studio/src/fonts.ts). On Linux the paths are the ones the worker
 * image installs (fonts-dejavu-core, fonts-liberation); the generated file records where each face came from. The
 * table holds only what text wrapping needs: advance widths in 1/1000 em for the characters the renderer supports.
 */
import { writeFileSync } from "node:fs";
import { basename } from "node:path";
import { readTtfMetrics } from "../src/fonts/ttf.js";

/** The scripts the renderer supports: Latin (with Turkish), Greek, Cyrillic and common punctuation and symbols. */
export const SUPPORTED_RANGES: [number, number][] = [
  [0x20, 0x7e],
  [0xa0, 0x24f],
  [0x370, 0x3ff],
  [0x400, 0x4ff],
  [0x2010, 0x2027],
  [0x2030, 0x203a],
  [0x20ac, 0x20ac],
  [0x2122, 0x2122],
];

/**
 * Code points left out although the Debian 12 fonts (fonts-liberation 1.07.4, the worker image) have them, because
 * the newer fonts-liberation 2.1.5 (Ubuntu 24.04, the CI runner) either lacks the glyph (U+2011, which would be drawn
 * as an empty box) or gives it another width (U+00B7 middle dot 278 against 333, U+040D 722 against 719). A character
 * whose width or existence depends on the font package version cannot be wrapped exactly, so it is refused instead.
 */
export const VERSION_DEPENDENT: ReadonlySet<number> = new Set([0xb7, 0x40d, 0x2011]);

const [, , out, ...faces] = process.argv;
if (!out || faces.length === 0) {
  console.error("usage: tsx scripts/generate-font-metrics.ts <out.ts> <faceKey=path> ...");
  process.exit(2);
}

type Run = [number, number[]];
const entries: string[] = [];
const sources: string[] = [];
for (const spec of faces) {
  const at = spec.indexOf("=");
  const key = spec.slice(0, at);
  const path = spec.slice(at + 1);
  const ttf = readTtfMetrics(path);
  const runs: Run[] = [];
  let current: Run | null = null;
  for (const [from, to] of SUPPORTED_RANGES) {
    for (let cp = from; cp <= to; cp++) {
      const adv = VERSION_DEPENDENT.has(cp) ? undefined : ttf.advance(cp);
      if (adv === undefined) {
        current = null;
        continue;
      }
      const milli = Math.round((adv * 1000) / ttf.unitsPerEm);
      if (current && current[0] + current[1].length === cp) current[1].push(milli);
      else {
        current = [cp, [milli]];
        runs.push(current);
      }
    }
  }
  const space = ttf.advance(0x20);
  entries.push(
    `  ${JSON.stringify(key)}: { upm: ${ttf.unitsPerEm}, ascent: ${Math.round((ttf.ascent * 1000) / ttf.unitsPerEm)}, descent: ${Math.round((-ttf.descent * 1000) / ttf.unitsPerEm)}, space: ${Math.round(((space ?? 0) * 1000) / ttf.unitsPerEm)}, runs: ${JSON.stringify(runs)} },`,
  );
  sources.push(`${key} <- ${basename(path)}`);
}

writeFileSync(
  out,
  `// GENERATED by packages/video-engine/scripts/generate-font-metrics.ts - do not edit by hand.\n// Advance widths in 1/1000 em, read from: ${sources.join("; ")}.\n// Verified against the installed fonts by packages/video-engine/src/fonts/font-metrics.test.ts.\nexport interface FaceMetricsData {\n  upm: number;\n  ascent: number;\n  descent: number;\n  space: number;\n  /** [first code point, advances of consecutive code points] */\n  runs: [number, number[]][];\n}\n\nexport const FONT_METRICS_DATA: Record<string, FaceMetricsData> = {\n${entries.join("\n")}\n};\n`,
  "utf8",
);
process.stdout.write(`wrote ${out} (${faces.length} faces)\n`);
